// Astraxis dataset types — generated by build_dataset.py (dist/*.json)

export type InvestigationId = "PSI-69" | "PSI-25";

export interface Investigation {
  id: InvestigationId;
  acronym: "FLEX" | "BASS-II";
  title: string;
  doi: string;
  license: string;
  research_area: string;
  sub_research_area: string;
  platform: string;
  hardware: string[];
  nasa_center: string;
  investigation_start: string; // ISO date
  investigation_end: string;
  fuel_phase: string;
  evidence_type: "experimental_observation";
  summary: string;
  source_url: string;
  source_files: string[];
  related_report?: { title: string; id: string; date: string; note: string };
  known_limitations: string[];
}

interface BaseTest {
  record_id: string;          // "PSI-69:001" | "PSI-25:B1"
  investigation_id: InvestigationId;
  test_id: string;            // identifier as written in the NASA source
  date: string | null;        // ISO date
  fuel_or_material: string;   // as written in the source
  material_class: string;
  flow_configuration: string | null;
  o2_initial_pct: number | null;
  pressure_mmhg: number | null;
  pressure_atm: number | null;
  quality_flags: string[];    // see dist/cleaning_log.csv for details
  // untouched source row lives in /public/data/raw-<investigation>.json (loaded on demand)
  source: { file: string; url: string; line?: number; sheet?: string; row?: number };
}

export interface FlexTest extends BaseTest {
  acronym: "FLEX";
  test_number: number;
  pi: null;
  time_gmt: string | null;
  n2_initial_pct: number | null;
  co2_initial_pct: number | null;
  he_initial_pct: number | null;
  diluent: "N2" | "CO2" | "He";
  droplet_initial_diameter_mm: number | null;
  flame_extinction_diameter_mm: number | null;
  burning_rate: number | null;   // UNIT UNVERIFIED — see field_dictionary.json
  burn_time_s: number | null;
  test_end: "Extinction" | "Disruption" | "Completion" | null;
}

export interface BassTest extends BaseTest {
  acronym: "BASS-II";
  test_number: null;
  pi: "Bhattacharjee" | "Ferkul" | "Miller" | "Olson" | "Fernandez-Pello" | "T'ien";
  pi_focus: string | null;
  gmt_day_of_year: number | null;
  sample_id: string;
  thickness_mm: number | null;
  rod_diameter_in: number | null;
  flow_restrictor: number | null;
  fan_display_raw: string | null;
  airflow_raw: string | null;
  airflow_initial_cm_s: number | null;
  airflow_sequence_cm_s: number[];
  airflow_notes: string[];
  airflow_changed_during_test: boolean;
  radiometer_gain_raw: string | null;
  still_frames: number | null;
  o2_final_pct: number | null;
  co2_initial_pct: number | null;
  co2_final_pct: number | null;
  co_initial_ppm: number | null;
  co_final_ppm: number | null;
  co_initial_over_range: boolean;
  co_final_over_range: boolean;
}

export type TestRecord = FlexTest | BassTest;

export interface FieldInfo {
  label: string;
  unit: string | null;
  unit_verified?: boolean;
  note?: string;
}
export type FieldDictionary = Record<string, FieldInfo>;

export interface CleaningLogEntry {
  record_id: string;
  field: string;
  raw_value: string;
  action: string;
  flag: string;
  note: string;
}
